import * as T from './three.js';
const materials=new Map(),textures=new Map();
export function fieldMaterial(kind='paint',color=0x6a7567){const key=kind+color;if(materials.has(key))return materials.get(key);const m=new T.MeshStandardMaterial({color,roughness:kind==='cloth'?.98:kind==='rubber'?.94:.7,metalness:['metal','paint'].includes(kind)?.55:0});materials.set(key,m);const names={paint:'GR_01_painted_alum',metal:'GR_03_black_anodized',cloth:'GR_04_weave',rubber:'GR_05_rubber',concrete:'GR_08_damp_concrete'};if(typeof document!=='undefined'&&names[kind]){const loader=new T.TextureLoader();for(const [property,suffix,srgb]of [['map','albedo',true],['normalMap','normal',false],['roughnessMap','rough',false]]){const file=names[kind]+'_'+suffix;let texture=textures.get(file);if(!texture){texture=loader.load('./assets/drones/textures/'+file+'.png');texture.wrapS=texture.wrapT=T.RepeatWrapping;texture.repeat.set(kind==='cloth'?3:1,kind==='cloth'?3:1);texture.anisotropy=4;if(srgb)texture.colorSpace=T.SRGBColorSpace;textures.set(file,texture);}m[property]=texture;}m.normalScale=new T.Vector2(.3,.3);}return m;}
export function fieldBox(group,x,y,z,w,h,d,material){const m=new T.Mesh(new T.BoxGeometry(w,h,d),material);m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;group.add(m);return m;}
function tube(group,points,r,material){const g=new T.TubeGeometry(new T.CatmullRomCurve3(points.map(p=>new T.Vector3(...p))),18,r,6,false),m=new T.Mesh(g,material);group.add(m);return m;}
function ring(group,x,y,z,r,t,material){const m=new T.Mesh(new T.TorusGeometry(r,t,6,32),material);m.rotation.y=Math.PI/2;m.position.set(x,y,z);group.add(m);return m;}
export function detailBike(g){g.name='BLACKLINE / field-built touring bike';const metal=fieldMaterial('metal',0x737e7b),rubber=fieldMaterial('rubber',0x4d5149),paint=fieldMaterial('paint',0x667665),cloth=fieldMaterial('cloth',0x737568);
 // Brake discs, calipers, fork gaiters, mudguards, hydraulic lines and drivetrain.
 for(const z of [-1,1]){ring(g,.14,.58,z,.27,.014,metal);for(let i=0;i<18;i++){const a=i*Math.PI/9;const m=fieldBox(g,.145,.58+Math.cos(a)*.23,z+Math.sin(a)*.23,.013,.045,.013,metal);m.rotation.x=-a;}fieldBox(g,.17,.75,z+.18,.085,.15,.085,rubber);for(const x of [-.19,.19])for(let j=0;j<7;j++)ring(g,x,.86+j*.055,z===-1?-.89+j*.023:.7-j*.02,.045,.008,rubber).rotation.set(Math.PI/2,0,0);
  const guard=new T.Mesh(new T.TorusGeometry(.62,.043,6,32,Math.PI),paint);guard.rotation.set(0,Math.PI/2,0);guard.position.set(0,.58,z);g.add(guard);
 }
 for(const side of [-1,1]){tube(g,[[side*.56,1.65,-.67],[side*.4,1.54,-.75],[side*.18,1.1,-.82],[side*.17,.75,-.85]],.012,rubber);fieldBox(g,side*.48,1.4,.72,.43,.025,.6,cloth);for(const z of [.48,.96])fieldBox(g,side*.69,1.15,z,.035,.5,.045,metal);fieldBox(g,side*.23,.92,.07,.02,.34,.4,paint);for(let i=0;i<6;i++)fieldBox(g,side*.245,.82+i*.047,.07,.012,.012,.34,metal);tube(g,[[side*.52,1.2,.45],[side*.55,1.38,.58],[side*.52,1.2,.83]],.016,metal);fieldBox(g,side*.36,.65,.1,.3,.035,.16,metal);}
 ring(g,.24,.7,.2,.17,.025,metal);tube(g,[[.27,.83,.2],[.27,.74,1],[.27,.43,1],[.27,.56,.2],[.27,.83,.2]],.012,rubber);
 fieldBox(g,0,1.14,1.2,.48,.06,.26,paint);tube(g,[[-.24,1.18,1.18],[-.26,1.45,.9],[.26,1.45,.9],[.24,1.18,1.18]],.018,metal);
 for(let i=0;i<3;i++)fieldBox(g,0,1.455,.08+i*.15,.4,.01,.008,cloth);
 const lamp=new T.Mesh(new T.CylinderGeometry(.12,.12,.08,24),fieldMaterial('metal',0xb1b9af));lamp.rotation.x=Math.PI/2;lamp.position.set(0,1.42,-.86);g.add(lamp);
}
export function detailTrailer(g){g.name='BLACKLINE / expedition utility trailer';const metal=fieldMaterial('metal',0x78847d),cloth=fieldMaterial('cloth',0x797964),paint=fieldMaterial('paint',0x667365),rubber=fieldMaterial('rubber',0x3c463e);
 for(const x of [-.56,.56]){fieldBox(g,x,.67,0,.06,.07,1.65,metal);for(let j=0;j<3;j++){const leaf=fieldBox(g,x,.36+j*.035,0,.055,.02,.8-j*.12,metal);leaf.rotation.x=j*.02;}fieldBox(g,x,.9,.04,.055,.46,1.42,cloth);for(const z of [-.6,.6]){fieldBox(g,x,.93,z,.07,.6,.042,rubber);fieldBox(g,x,1.04,z-.02,.087,.07,.045,metal);}fieldBox(g,x*1.4,.7,0,.3,.055,.84,paint);tube(g,[[x,.5,-.55],[x,.68,-.48],[x,.7,.5],[x,.5,.55]],.024,metal);}
 for(const z of [-.74,.74]){fieldBox(g,0,1.3,z,1.12,.05,.04,metal);for(const x of [-.43,.43]){fieldBox(g,x,.85,z,.13,.18,.045,metal);fieldBox(g,x,.84,z*1.035,.035,.07,.02,rubber);}}
 tube(g,[[-.13,.48,-.92],[-.1,.32,-1.4],[.12,.3,-1.5],[.14,.48,-1.9]],.015,metal);fieldBox(g,0,.53,-1.9,.2,.12,.23,paint);fieldBox(g,0,.61,-1.87,.06,.05,.16,metal);
 for(let i=0;i<7;i++)fieldBox(g,.14,1.54,.3+i*.07,.43,.02,.014,rubber);
 tube(g,[[.3,1.4,-.5],[.47,1.32,-.55],[.52,.8,-.6],[.2,.62,-.9]],.011,rubber);
}
export function detailPerson(g,{head,arms,legs,color}){const cloth=fieldMaterial('cloth',color),dark=fieldMaterial('cloth',0x555c4b),leather=fieldMaterial('rubber',0x4a4236),metal=fieldMaterial('metal',0x827e6b);
 g.traverse(o=>{if(!o.isMesh||!o.material?.color)return;const c=o.material.color.getHex();if(c===color)o.material=cloth;else if([0x394442,0x3b413c,0x494c3e,0x303b37].includes(c))o.material=dark;else if([0x17201f,0x282e29].includes(c))o.material=leather;else if(c===0x8a745a)o.material=new T.MeshStandardMaterial({color:0x9c8065,roughness:.88,metalness:0});});
 fieldBox(g,0,1.41,.27,.014,.5,.018,metal);for(const side of [-1,1]){const collar=fieldBox(g,side*.12,1.74,.15,.19,.18,.055,cloth);collar.rotation.z=-side*.35;tube(g,[[side*.22,1.7,.18],[side*.2,1.4,.29],[side*.18,1.13,.22]],.015,leather);fieldBox(g,side*.16,1.05,.19,.08,.025,.02,metal);}
 const variant=Math.abs(Math.round(color))%3;g.userData.costume=variant===0?'hood & scarf':variant===1?'field cap':'work goggles';
 for(const side of [-1,1]){const cheek=new T.Mesh(new T.SphereGeometry(.067,12,8),new T.MeshStandardMaterial({color:0xa0846d,roughness:.9}));cheek.position.set(side*.105,-.065,.151);cheek.scale.set(1,.6,.38);head.add(cheek);const ear=new T.Mesh(new T.SphereGeometry(.052,10,8),cheek.material);ear.position.set(side*.186,-.015,.014);ear.scale.set(.55,1,.7);head.add(ear);}
 if(variant===1){const brim=fieldBox(head,0,.15,.16,.35,.025,.2,dark);brim.rotation.x=.08;}else if(variant===2){fieldBox(head,0,.03,.186,.33,.075,.033,metal);for(const side of [-1,1])fieldBox(head,side*.082,.03,.207,.126,.054,.012,new T.MeshStandardMaterial({color:0x566563,roughness:.2,metalness:.4}));}else{const scarf=new T.Mesh(new T.TorusGeometry(.18,.055,8,20),cloth);scarf.rotation.x=Math.PI/2;scarf.position.set(0,-.17,0);head.add(scarf);}
 for(const [i,arm]of arms.entries()){const side=i?1:-1;for(let j=0;j<3;j++)fieldBox(arm,side*.06,-.2-j*.035,.092,.13,.013,.02,dark);fieldBox(arm,side*.09,-.53,.13,.16,.045,.11,leather);for(let f=0;f<4;f++)tube(arm,[[side*.08+(f-1.5)*.025,-.64,.235],[side*.08+(f-1.5)*.025,-.71,.26],[side*.08+(f-1.5)*.022,-.75,.24]],.012,leather);}
 for(const leg of legs){for(let j=0;j<4;j++)fieldBox(leg,0,-.7+j*.03,.245,.13,.008,.02,metal);fieldBox(leg,0,-.855,.09,.26,.025,.44,leather);}
}
